SELECT a.Id AS AngleId, a.BuildId, a.View, a.Status AS AngleStatus, a.OutputArtifactId AS AngleOutput, at.Id AS AttemptId, at.AttemptNumber, at.Status AS AttemptStatus, at.OutputArtifactId AS AttemptOutput, i.Status AS ImageStatus, i.FileRelativePath FROM CharacterIdentityAngles a LEFT JOIN CharacterIdentityAngleAttempts at ON at.AngleId = a.Id LEFT JOIN SceneAssetImages i ON i.Id = at.OutputArtifactId WHERE a.BuildId = '49c3175356874e908b181cad815f7141' ORDER BY a.View, at.AttemptNumber;
